// Preprod backend: talks to the real Midnight network through the Lace wallet
// (DApp Connector API v4) and Midnight.js 4.1.1. Proofs are generated by the
// wallet's proving provider, or by a proof server if the wallet exposes one.

import { Buffer } from 'buffer';
import semver from 'semver';
import type { ConnectedAPI, InitialAPI } from '@midnight-ntwrk/dapp-connector-api';
import { deployContract, findDeployedContract, type FoundContract } from '@midnight-ntwrk/midnight-js-contracts';
import { FetchZkConfigProvider } from '@midnight-ntwrk/midnight-js-fetch-zk-config-provider';
import { httpClientProofProvider } from '@midnight-ntwrk/midnight-js-http-client-proof-provider';
import { indexerPublicDataProvider } from '@midnight-ntwrk/midnight-js-indexer-public-data-provider';
import { setNetworkId } from '@midnight-ntwrk/midnight-js-network-id';
import { createProofProvider, type MidnightProviders, type UnboundTransaction } from '@midnight-ntwrk/midnight-js-types';
import { CompiledContract } from '@midnight-ntwrk/midnight-js-protocol/compact-js';
import { fromHex as rtFromHex, toHex as rtToHex, rawTokenType } from '@midnight-ntwrk/midnight-js-protocol/compact-runtime';
import {
  Transaction,
  type Binding,
  type FinalizedTransaction,
  type Proof,
  type SignatureEnabled,
} from '@midnight-ntwrk/midnight-js-protocol/ledger';
import { Contract, ledger, witnesses, withOpening, pureCircuits, type PayrollPrivateState } from '@payroll/midnight-contract';
import { localPrivateStateProvider } from './private-state';
import {
  employeeRole,
  publicKeyFor,
  secretKeyFor,
  type PayrollBackend,
  type PayslipOpening,
  type RoleId,
  type TxInfo,
} from './core';

if (typeof globalThis.Buffer === 'undefined') globalThis.Buffer = Buffer as unknown as typeof globalThis.Buffer;

export const MIDNIGHT_NETWORK_ID = process.env.NEXT_PUBLIC_MIDNIGHT_NETWORK_ID ?? 'preprod';
const FALLBACK_PROOF_SERVER = process.env.NEXT_PUBLIC_PROOF_SERVER_URL ?? 'http://localhost:6300';
const COMPATIBLE_CONNECTOR_API = '4.x';

type PayrollContract = Contract<PayrollPrivateState>;
type CircuitId = 'fundPeriod' | 'issuePayslip' | 'claimPayslip' | 'attestPeriod';
type Providers = MidnightProviders<CircuitId, RoleId, PayrollPrivateState>;

const compiledPayroll = CompiledContract.make<PayrollContract>('Payroll', Contract<PayrollPrivateState>).pipe(
  CompiledContract.withWitnesses(witnesses),
  CompiledContract.withCompiledFileAssets('/midnight/payroll'),
);

/** Finds a Midnight wallet (Lace) implementing DApp Connector API 4.x. */
export function findMidnightWallet(): InitialAPI | undefined {
  const injected = (globalThis as { midnight?: Record<string, unknown> }).midnight;
  if (!injected) return undefined;
  return Object.values(injected).find(
    (w): w is InitialAPI =>
      !!w && typeof w === 'object' && 'apiVersion' in w && semver.satisfies(String((w as InitialAPI).apiVersion), COMPATIBLE_CONNECTOR_API),
  );
}

export async function connectMidnightWallet(): Promise<ConnectedAPI> {
  // Extensions inject window.midnight shortly after load.
  for (let i = 0; i < 20 && !findMidnightWallet(); i++) await new Promise(r => setTimeout(r, 100));
  const wallet = findMidnightWallet();
  if (!wallet) throw new Error('Lace (Midnight) wallet not found. Install Lace and enable Midnight Preprod.');
  setNetworkId(MIDNIGHT_NETWORK_ID);
  return wallet.connect(MIDNIGHT_NETWORK_ID);
}

async function buildProviders(api: ConnectedAPI): Promise<Providers> {
  const config = await api.getConfiguration();
  const zkConfigProvider = new FetchZkConfigProvider<CircuitId>(`${window.location.origin}/midnight/payroll`, fetch.bind(window));
  const shielded = await api.getShieldedAddresses();

  let proofProvider;
  try {
    proofProvider = createProofProvider(await api.getProvingProvider(zkConfigProvider));
  } catch {
    proofProvider = httpClientProofProvider(config.proverServerUri ?? FALLBACK_PROOF_SERVER, zkConfigProvider);
  }

  return {
    privateStateProvider: localPrivateStateProvider<RoleId, PayrollPrivateState>(),
    zkConfigProvider,
    proofProvider,
    publicDataProvider: indexerPublicDataProvider(config.indexerUri, config.indexerWsUri),
    walletProvider: {
      getCoinPublicKey: () => shielded.shieldedCoinPublicKey,
      getEncryptionPublicKey: () => shielded.shieldedEncryptionPublicKey,
      balanceTx: async (tx: UnboundTransaction): Promise<FinalizedTransaction> => {
        const { tx: balanced } = await api.balanceUnsealedTransaction(rtToHex(tx.serialize()));
        return Transaction.deserialize<SignatureEnabled, Proof, Binding>('signature', 'proof', 'binding', rtFromHex(balanced));
      },
    },
    midnightProvider: {
      submitTx: async (tx: FinalizedTransaction) => {
        await api.submitTransaction(rtToHex(tx.serialize()));
        return tx.identifiers()[0];
      },
    },
  } as Providers;
}

export class PreprodPayrollBackend implements PayrollBackend {
  readonly mode = 'preprod' as const;
  private readonly handles = new Map<RoleId, Promise<FoundContract<PayrollContract>>>();

  private constructor(
    readonly contractAddress: string,
    private readonly api: ConnectedAPI,
    private readonly providers: Providers,
  ) {}

  /** Deploys a new payroll contract; the connected wallet pays the fees. */
  static async deploy(api: ConnectedAPI): Promise<PreprodPayrollBackend> {
    const providers = await buildProviders(api);
    const deployed = await deployContract(providers, {
      compiledContract: compiledPayroll,
      privateStateId: 'employer',
      initialPrivateState: { secretKey: secretKeyFor('employer'), openings: {} },
      args: [publicKeyFor('auditor')],
    });
    return new PreprodPayrollBackend(deployed.deployTxData.public.contractAddress, api, providers);
  }

  static async join(api: ConnectedAPI, contractAddress: string): Promise<PreprodPayrollBackend> {
    const backend = new PreprodPayrollBackend(contractAddress, api, await buildProviders(api));
    await backend.readLedger(); // fails fast on a wrong address or network
    return backend;
  }

  async readLedger() {
    const state = await this.providers.publicDataProvider.queryContractState(this.contractAddress);
    if (!state) throw new Error(`No payroll contract at ${this.contractAddress} on ${MIDNIGHT_NETWORK_ID}`);
    return ledger(state.data);
  }

  /** Joins the contract as `role`, seeding that role's private state. */
  private async as(role: RoleId, openings: Record<string, PayslipOpening> = {}) {
    this.providers.privateStateProvider.setContractAddress(this.contractAddress);
    const state: PayrollPrivateState = { secretKey: secretKeyFor(role), openings };
    await this.providers.privateStateProvider.set(role, state);
    if (!this.handles.has(role)) {
      this.handles.set(
        role,
        findDeployedContract(this.providers, {
          contractAddress: this.contractAddress,
          compiledContract: compiledPayroll,
          privateStateId: role,
          initialPrivateState: state,
        }),
      );
    }
    return this.handles.get(role)!;
  }

  private static tx(data: { public: { txId: unknown } }): TxInfo {
    return { txId: String(data.public.txId), mode: 'preprod' };
  }

  async fundPeriod(period: bigint, budget: bigint) {
    const c = await this.as('employer');
    return PreprodPayrollBackend.tx(await c.callTx.fundPeriod(period, budget));
  }

  async issuePayslip(employeePk: Uint8Array, period: bigint, opening: PayslipOpening) {
    const { openings } = withOpening({ secretKey: new Uint8Array(), openings: {} }, pureCircuits.payslipId(employeePk, period), opening);
    const c = await this.as('employer', openings);
    return PreprodPayrollBackend.tx(await c.callTx.issuePayslip(employeePk, period));
  }

  async claimPayslip(employeeId: string, period: bigint, opening: PayslipOpening) {
    const role = employeeRole(employeeId);
    const { openings } = withOpening(
      { secretKey: new Uint8Array(), openings: {} },
      pureCircuits.payslipId(publicKeyFor(role), period),
      opening,
    );
    const c = await this.as(role, openings);
    return PreprodPayrollBackend.tx(await c.callTx.claimPayslip(period));
  }

  async attestPeriod(period: bigint) {
    const c = await this.as('auditor');
    return PreprodPayrollBackend.tx(await c.callTx.attestPeriod(period));
  }

  /** Pays net salary as shielded pTWD from the employer's wallet; amounts stay private. */
  async payEmployee(shieldedAddress: string, amount: bigint): Promise<TxInfo> {
    const tokenType = rawTokenType(pureCircuits.payTokenDomain(), this.contractAddress);
    const { tx } = await this.api.makeTransfer([{ kind: 'shielded', type: tokenType, value: amount, recipient: shieldedAddress }]);
    await this.api.submitTransaction(tx);
    const finalized = Transaction.deserialize<SignatureEnabled, Proof, Binding>('signature', 'proof', 'binding', rtFromHex(tx));
    return { txId: String(finalized.identifiers()[0]), mode: 'preprod' };
  }
}
